# 0037-34.02 Deterministic Reference Verifier & Negative Harness
# Specification ID: 0037-34.02-reference-verifier@v2
# Generation Domain: issue-cutover-reference-verification@v2

import copy
import hashlib
import json
import os
import platform
import subprocess
import sys

class ReferenceVerificationError(Exception):
    pass

def compute_sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(65536):
            h.update(chunk)
    return "sha256:" + h.hexdigest()

def compute_sha256_bytes(b):
    return "sha256:" + hashlib.sha256(b).hexdigest()

def dict_raise_on_duplicates(ordered_pairs):
    d = {}
    for k, v in ordered_pairs:
        if k in d:
            raise ReferenceVerificationError(f"Duplicate field detected during JSON deserialization: {k}")
        d[k] = v
    return d

def parse_reference_json(raw_text):
    return json.loads(raw_text, object_pairs_hook=dict_raise_on_duplicates)

def run_git(args, cwd):
    res = subprocess.run(["git"] + args, cwd=cwd, capture_output=True, text=True)
    return res.returncode, res.stdout.strip(), res.stderr.strip()

def verify_reference_structure(data):
    if not isinstance(data, dict):
        raise ReferenceVerificationError("Top-level payload must be a JSON object")

    if data.get("schema") != "issue-cutover-reference@v1":
        raise ReferenceVerificationError(f"Invalid schema: {data.get('schema')}")
    if data.get("transaction_id") != "0037-34.01-authority-switch-20260905":
        raise ReferenceVerificationError(f"Invalid transaction_id: {data.get('transaction_id')}")
    if data.get("task_id") != "0037-34.02":
        raise ReferenceVerificationError(f"Invalid task_id: {data.get('task_id')}")

    required_keys = {
        "schema", "transaction_id", "task_id", "signer_authority", "cutover_execution",
        "predecessor", "governing_decisions", "architect_scope_reviews", "bound_package",
        "approvals", "frozen_selector", "logical_dispositions", "retained_deferred_closure_obligations",
        "verifier_specification", "negative_matrix", "signature_verification_results", "integrator_receipts"
    }
    missing = required_keys - set(data.keys())
    if missing:
        raise ReferenceVerificationError(f"Missing required field(s): {sorted(list(missing))}")

    extra_k = set(data.keys()) - required_keys
    if extra_k:
        raise ReferenceVerificationError(f"Unknown field detected in schema: {sorted(list(extra_k))[0]}")

    # Bound package check (must be non-empty and strictly typed)
    pkg = data.get("bound_package")
    if not isinstance(pkg, dict) or not pkg:
        raise ReferenceVerificationError("Missing required field(s): ['bound_package'] or bound_package is empty")
    pkg_required_keys = {
        "audit_commit", "forward_patch_sha256", "ledger_artifact_sha256", "ledger_semantic_sha256",
        "manifest_sha256", "package_sha256", "preparation_commit", "rollback_patch_sha256"
    }
    pkg_missing = pkg_required_keys - set(pkg.keys())
    if pkg_missing:
        raise ReferenceVerificationError(f"Missing bound_package field(s): {sorted(list(pkg_missing))}")
    pkg_extra = set(pkg.keys()) - pkg_required_keys
    if pkg_extra:
        raise ReferenceVerificationError(f"Unknown field detected in bound_package: {sorted(list(pkg_extra))[0]}")

    # Cutover execution check
    cut = data.get("cutover_execution")
    if not isinstance(cut, dict):
        raise ReferenceVerificationError("cutover_execution must be a dict")
    cut_required_keys = {
        "commit_oid", "control_commit", "control_tree", "control_tree_sha256",
        "cutover_utc", "transaction_ref", "tree_oid", "tree_sha256"
    }
    if set(cut.keys()) != cut_required_keys:
        extra = set(cut.keys()) - cut_required_keys
        if extra:
            raise ReferenceVerificationError(f"Unknown field in cutover_execution: {sorted(list(extra))[0]}")
        raise ReferenceVerificationError(f"Missing cutover_execution field(s): {sorted(list(cut_required_keys - set(cut.keys())))}")

    if cut.get("commit_oid") != "b9149771c01e21acd893783e25026d9947b9e985":
        raise ReferenceVerificationError(f"Wrong cutover commit_oid: {cut.get('commit_oid')}")
    if cut.get("control_commit") != "36b349fb86c9aa5579f46d89bea73096af35ad11":
        raise ReferenceVerificationError(f"Wrong control_commit: {cut.get('control_commit')}")
    if cut.get("control_tree") != "8d3cb2789fe4e4635fe31985c7df35c2cb93c537":
        raise ReferenceVerificationError(f"Wrong control_tree: {cut.get('control_tree')}")
    if cut.get("tree_oid") != "cff4f993bb43fda5e23aa1d29ca34c67e4959b39":
        raise ReferenceVerificationError(f"Wrong cutover tree_oid: {cut.get('tree_oid')}")
    if cut.get("tree_sha256") != "sha256:1afa28699324f6a492ecac472d447c122932fb9b872ed38afbd83535af1cecba":
        raise ReferenceVerificationError(f"Wrong cutover tree_sha256: {cut.get('tree_sha256')}")

    # Approvals check
    apps = data.get("approvals")
    if not isinstance(apps, dict):
        raise ReferenceVerificationError("approvals must be a dict")
    expected_purposes = {"process", "security-privacy", "release"}
    if set(apps.keys()) != expected_purposes:
        raise ReferenceVerificationError(f"Wrong approval purposes: expected {sorted(list(expected_purposes))}, got {sorted(list(apps.keys()))}")

    expected_app_data = {
        "process": {
            "commit_oid": "5955b2e5c32b3698df661384d0a3567db8e93f28",
            "ref": "refs/autodocs/approvals/0037/0037-34.01-authority-switch-20260905/process",
            "signing_occasion": "0037-33-process-20260905T094410Z",
            "validity": "valid"
        },
        "security-privacy": {
            "commit_oid": "00f972ccf45cc760e2857268b95926534490ebfe",
            "ref": "refs/autodocs/approvals/0037/0037-34.01-authority-switch-20260905/security-privacy",
            "signing_occasion": "0037-33-security-privacy-20260905T094420Z",
            "validity": "valid"
        },
        "release": {
            "commit_oid": "88e3cdd8e7a32fe2233fb9d27f07e24b4d03954c",
            "ref": "refs/autodocs/approvals/0037/0037-34.01-authority-switch-20260905/release",
            "signing_occasion": "0037-33-release-20260905T094430Z",
            "validity": "valid"
        }
    }
    app_field_keys = {"commit_oid", "ref", "signing_occasion", "validity"}
    for purp, exp in expected_app_data.items():
        act = apps.get(purp)
        if not isinstance(act, dict):
            raise ReferenceVerificationError(f"Approval for {purp} must be a dict")
        if set(act.keys()) != app_field_keys:
            extra = set(act.keys()) - app_field_keys
            if extra:
                raise ReferenceVerificationError(f"Unknown field in approval {purp}: {sorted(list(extra))[0]}")
            raise ReferenceVerificationError(f"Missing field in approval {purp}: {sorted(list(app_field_keys - set(act.keys())))}")
        if act.get("validity") != "valid":
            raise ReferenceVerificationError(f"Stale/revoked approval condition for {purp}: validity={act.get('validity')}")
        if act.get("commit_oid") != exp["commit_oid"]:
            raise ReferenceVerificationError(f"Wrong approval commit_oid for {purp}: expected {exp['commit_oid']}, got {act.get('commit_oid')}")
        if act.get("ref") != exp["ref"]:
            raise ReferenceVerificationError(f"Wrong approval ref for {purp}: expected {exp['ref']}, got {act.get('ref')}")

    # Frozen selector check
    sel = data.get("frozen_selector")
    if not isinstance(sel, dict):
        raise ReferenceVerificationError("frozen_selector must be a dict")
    sel_keys = {"authority_epoch", "authority_profile", "digest", "write_phase"}
    if set(sel.keys()) != sel_keys:
        raise ReferenceVerificationError("frozen_selector field mismatch")
    if sel.get("authority_profile") != "issue-store" or sel.get("authority_epoch") != "issue-store-write-frozen" or sel.get("write_phase") != "frozen":
        raise ReferenceVerificationError(f"Frozen selector state mismatch: {sel}")
    if sel.get("digest") != "sha256:13b516474ee10827f8d1364c7c43f74ef80adfbf7b1e92f072dea8531f2b7ee0":
        raise ReferenceVerificationError(f"Selector digest drift: expected sha256:13b516474ee10827f8d1364c7c43f74ef80adfbf7b1e92f072dea8531f2b7ee0, got {sel.get('digest')}")

    # Predecessor check
    pred = data.get("predecessor")
    if not isinstance(pred, dict):
        raise ReferenceVerificationError("predecessor must be a dict")
    pred_keys = {"commit_oid", "sequence", "tree_oid"}
    if set(pred.keys()) != pred_keys:
        extra = set(pred.keys()) - pred_keys
        if extra:
            raise ReferenceVerificationError(f"Unknown field detected in predecessor: {sorted(list(extra))[0]}")
        raise ReferenceVerificationError(f"Missing predecessor field: {sorted(list(pred_keys - set(pred.keys())))}")
    if pred.get("commit_oid") != "b9149771c01e21acd893783e25026d9947b9e985":
        raise ReferenceVerificationError(f"Predecessor commit drift: expected b9149771c01e21acd893783e25026d9947b9e985, got {pred.get('commit_oid')}")
    if pred.get("sequence") != 1:
        raise ReferenceVerificationError(f"Predecessor sequence drift: expected 1, got {pred.get('sequence')}")
    if pred.get("tree_oid") != "cff4f993bb43fda5e23aa1d29ca34c67e4959b39":
        raise ReferenceVerificationError(f"Predecessor tree drift: expected cff4f993bb43fda5e23aa1d29ca34c67e4959b39, got {pred.get('tree_oid')}")

    # Logical dispositions check
    disps = data.get("logical_dispositions")
    if not isinstance(disps, dict):
        raise ReferenceVerificationError("logical_dispositions must be a dict")
    expected_items = {"0037-32", "0037-33", "0037-34", "0037-34.02"}
    if set(disps.keys()) != expected_items:
        extra = set(disps.keys()) - expected_items
        missing_items = expected_items - set(disps.keys())
        if extra:
            raise ReferenceVerificationError(f"Extra item(s) in logical dispositions: {sorted(list(extra))}")
        if missing_items:
            raise ReferenceVerificationError(f"Missing item(s) in logical dispositions: {sorted(list(missing_items))}")

    disp_field_keys = {"acceptance_granted", "disposition", "issue_state", "materialization_task", "start_gate_satisfied"}
    for item_id, item_disp in disps.items():
        if set(item_disp.keys()) != disp_field_keys:
            raise ReferenceVerificationError(f"Invalid keys in disposition for {item_id}")
        if item_disp.get("acceptance_granted") is not False:
            raise ReferenceVerificationError(f"Acceptance inflation detected for {item_id}: acceptance_granted={item_disp.get('acceptance_granted')}")
        if item_disp.get("issue_state") != "open":
            raise ReferenceVerificationError(f"Acceptance inflation / state mutation detected for {item_id}: issue_state={item_disp.get('issue_state')}")
        if item_disp.get("disposition") != "completed":
            raise ReferenceVerificationError(f"Invalid disposition for {item_id}: {item_disp.get('disposition')}")
        if item_disp.get("start_gate_satisfied") is not True:
            raise ReferenceVerificationError(f"Start gate not satisfied for {item_id}")
        if item_disp.get("materialization_task") != "0037-40":
            raise ReferenceVerificationError(f"Wrong materialization task for {item_id}: {item_disp.get('materialization_task')}")

    # Retained deferred closure obligations check
    retained = data.get("retained_deferred_closure_obligations")
    expected_retained = ["0037-31", "0037-34.01", "0037-32", "0037-33", "0037-34.02", "0037-34"]
    if not isinstance(retained, list) or sorted(retained) != sorted(expected_retained):
        missing_retained = set(expected_retained) - set(retained or [])
        if missing_retained:
            raise ReferenceVerificationError(f"Missing deferred obligation(s): {sorted(list(missing_retained))}")
        raise ReferenceVerificationError(f"Retained deferred obligations mismatch: expected {expected_retained}, got {retained}")

    return True

def verify_tree_delta(repo_dir, base_commit="b9149771c01e21acd893783e25026d9947b9e985", target_commit="22de9468f8b15750f18c7eac1d47e0fca220eac9"):
    code, out, err = run_git(["diff-tree", "-r", "--name-only", "--no-commit-id", base_commit, target_commit], cwd=repo_dir)
    if code != 0:
        raise ReferenceVerificationError(f"Git diff-tree query failed: {err}")
    changed = [line.strip() for line in out.splitlines() if line.strip()]
    allowed = {"provenance/migrations/issue-store/0037-34.02-reference.json"}
    for p in changed:
        if p not in allowed:
            raise ReferenceVerificationError(f"Forbidden tree delta detected: {p} was modified outside allowed scope {allowed}")
    return True

def verify_all(reference_json_path, repo_dir):
    with open(reference_json_path, "rb") as f:
        raw_bytes = f.read()

    # 1. Parse JSON with duplicate key detection
    data = parse_reference_json(raw_bytes.decode("utf-8"))

    # 2. Strict structure validation
    verify_reference_structure(data)

    # 3. Real Git Commit Signatures verification
    allowed_signers = os.path.join(repo_dir, "issues/_policy/allowed_signers")
    commits = [
        ("process_approval", "5955b2e5c32b3698df661384d0a3567db8e93f28"),
        ("security_privacy_approval", "00f972ccf45cc760e2857268b95926534490ebfe"),
        ("release_approval", "88e3cdd8e7a32fe2233fb9d27f07e24b4d03954c"),
        ("cutover_commit", "b9149771c01e21acd893783e25026d9947b9e985"),
        ("reference_commit_22de", "22de9468f8b15750f18c7eac1d47e0fca220eac9"),
        ("reference_evidence_commit_e186", "e186757e5417fbd7b4d89f2cf9ca6a7567642eeb"),
        ("reference_verifier_commit_74ea", "74eae77f27346ca43ff9a4fe5226440916776f4a")
    ]
    for label, oid in commits:
        code, out, err = run_git(["-c", f"gpg.ssh.allowedSignersFile={allowed_signers}", "verify-commit", "--raw", oid], repo_dir)
        if code != 0:
            raise ReferenceVerificationError(f"Signature verification failed for {label} ({oid}): {err}")

    # 4. Real Git Tree Delta check on 34.02 reference lineage
    verify_tree_delta(repo_dir, "b9149771c01e21acd893783e25026d9947b9e985", "22de9468f8b15750f18c7eac1d47e0fca220eac9")

    # 5. Source hash self-check
    spec = data.get("verifier_specification", {})
    source_code = spec.get("source_code", "")
    expected_hash = spec.get("source_sha256", "")
    actual_hash = compute_sha256_bytes(source_code.encode("utf-8"))
    if actual_hash != expected_hash:
        raise ReferenceVerificationError(f"Verifier source hash mismatch: expected {expected_hash}, computed {actual_hash}")

    return True

