                case_res["observed"] = "ALLOWED"
                case_res["status"] = "FAIL"
                case_res["stable_reason"] = "Verifier unexpectedly allowed invalid data"
            except ReferenceVerificationError as e:
                case_res["observed"] = "BLOCKED"
                case_res["status"] = "PASS"
                case_res["stable_reason"] = str(e)
        elif test_type == "json_parse":
            raw_dup_json = '{"schema": "issue-cutover-reference@v1", "schema": "issue-cutover-reference@v2"}'
            try:
                parse_reference_json(raw_dup_json)
                case_res["observed"] = "ALLOWED"
                case_res["status"] = "FAIL"
                case_res["stable_reason"] = "JSON decoder allowed duplicate keys"
            except ReferenceVerificationError as e:
                case_res["observed"] = "BLOCKED"
                case_res["status"] = "PASS"
