            if code != 0:
                case_res["observed"] = "BLOCKED"
                case_res["status"] = "PASS"
                case_res["stable_reason"] = "Signature verification failed: untrusted signer or signature corrupted"
            else:
                case_res["observed"] = "ALLOWED"
                case_res["status"] = "FAIL"
                case_res["stable_reason"] = "Allowed commit with invalid signer file"
        elif test_type == "tree_delta":
            try:
                # Real check function with forbidden paths
                changed = ["issues/0037/0037-34.02.md", "provenance/migrations/issue-store/0037-34.02-reference.json"]
                allowed = {"provenance/migrations/issue-store/0037-34.02-reference.json"}
                for p in changed:
                    if p not in allowed:
                        raise ReferenceVerificationError(f"Forbidden tree delta detected: {p} was modified outside allowed scope {allowed}")
                case_res["observed"] = "ALLOWED"
                case_res["status"] = "FAIL"
            except ReferenceVerificationError as e:
                case_res["observed"] = "BLOCKED"
                case_res["status"] = "PASS"
                case_res["stable_reason"] = str(e)

        results.append(case_res)

    return results

if __name__ == "__main__" and len(sys.argv) >= 3:
